import * as E from './engine.js';
import {buildHints} from './build-hints.js';
import {tile} from './tiles.js';
import {renderPatternGuide,renderPatternResults} from './pattern-guide.js';
import {buildSettlementSnapshot,createSettlementPlayer} from './settlement-adapter.js';
import {captureGameState,trackGameAction} from './analytics/game-adapter.js';

const app=document.querySelector('#app'),wrap=document.querySelector('#settlement-wrap'),SAVE='jade-run-v4',PREF='jade-run-sound';
let game=null,legacy=false;try{game=E.restore(localStorage.getItem(SAVE));legacy=!!(localStorage.getItem('jade-run-v1')||localStorage.getItem('jade-run-v2')||localStorage.getItem('jade-run-v3'));}catch{}
let screen='home',mode=game?.mode||'mcr',selected=[],formedSelected=[],dialog=null,sound=false,notificationTimer,player=null,speed=1,skipped=false,inputMethod='pointer';
let guideMode=mode,guideFilter='all',guideQuery='',buildExpanded=false,lastBuildKey='',lastActiveIds=new Set();
const shapeName=shape=>({normal:'四面子一雀头',pairs:'七对',orphans:'十三幺结构',knitted:'组合龙',unconnected:'不靠牌形'})[shape]||'完整牌形';
let reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
try{sound=localStorage.getItem(PREF)==='true';}catch{}
const fmt=n=>new Intl.NumberFormat('zh-CN',{maximumFractionDigits:6}).format(n??0);
const signed=n=>(n>=0?'+':'')+fmt(n);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(act,text,cls='',attrs='')=>`<button class="${cls}" data-act="${act}" ${attrs}>${text}</button>`;
let artwork={relics:{}};
fetch('./art/manifest.json').then(r=>r.json()).then(data=>{artwork=data;for(const key of ['page','board','shop']){const src=data.backgrounds?.[key];if(typeof src==='string'&&/^\.\/art\/[a-zA-Z0-9_./-]+$/.test(src))document.documentElement.style.setProperty('--art-'+key,`url("${src}")`);}render();}).catch(()=>{});
function persist(){try{localStorage.setItem(SAVE,JSON.stringify(game));}catch{toast('无法保存进度，本次游戏仍可继续。');}}
function toast(msg){clearTimeout(notificationTimer);const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');notificationTimer=setTimeout(()=>el.classList.remove('show'),3600);}
const capture=()=>{try{return captureGameState(game);}catch{return null;}};
function track(action,before,result,context={}){try{Promise.resolve(trackGameAction(action,before,game,result,{input_method:inputMethod,...context})).catch(()=>{});}catch{}}
const chosen=()=>[...selected,...formedSelected];
const locked=()=>new Set(game.kongs.flatMap(k=>k.tileIds));
function clear(){selected=[];formedSelected=[];}
function mutate(action,fn,context={},message=''){const before=capture();const result=fn();track(action,before,result,context);if(result===false||result?.valid===false||result?.ok===false){toast(result?.reason||'当前无法执行，请检查选择和剩余资源。');return false;}clear();dialog=null;persist();render();if(message)toast(typeof message==='function'?message(result):message);return true;}
function emblem(id,showcase=false){const r=E.relic(id),src=artwork.relics?.[id];return `<span class="relic-emblem${showcase?' relic-showcase':''}" data-art="${id}"><span>${r.icon}</span>${typeof src==='string'&&/^\.\/art\//.test(src)?`<img src="${esc(src)}" alt="${showcase?esc(r.name)+'奇物原画':''}" loading="${showcase?'eager':'lazy'}" width="256" height="256">`:''}</span>`;}
function header(){return `<header class="topbar"><a href="#" data-act="home" class="brand"><span class="brand-tile">雀</span><span>叠雀<small>MAHJONG · ROGUELIKE</small></span></a><div class="top-actions"><span class="edition">自由成牌 <i>v0.4</i></span>${button('sound',sound?'♪ 声音开':'♪ 声音关','text-btn')}${button('patterns','番型图鉴 ↗','text-btn')}${button('rules','玩法说明','text-btn')}</div></header>`;}
function home(){const resumable=game&&!['victory','defeat'].includes(game.phase);return `<main class="home"><div class="home-intro"><div class="eyebrow"><span class="mini-line"></span> 一场关于组合与奇遇的牌局</div><h1>一张，也能<br>叠出<span>青山。</span></h1><p class="home-copy">自由出牌，落成十四张。<br>用奇物改写牌面，让番型与倍率一起生长。</p><div class="home-facts"><span>六重山境</span><span>${E.RELICS.length} 件奇物</span><span>累计得分闯关</span></div><div class="fan-art" aria-hidden="true"><span class="fan-orbit"></span>${[0,9,18,32,4].map((t,i)=>`<div style="--i:${i}">${tile(t)}</div>`).join('')}<span class="art-seal">好牌<br>成双</span></div></div><section class="mode-panel"><div class="section-kicker">启程前 · 选择你的规则</div><h2>这一局，怎么打？</h2><div class="mode-options">${['mcr','riichi'].map(m=>`<button class="mode-card ${mode===m?'active':''}" data-act="mode" data-mode="${m}" aria-pressed="${mode===m}"><span class="mode-symbol">${m==='mcr'?'国':'和'}</span><span><strong>${E.MODES[m].name}</strong><small>${m==='mcr'?'番型相叠，百般成局':'役种相连，奇物成势'}</small></span><span class="radio-dot"></span></button>`).join('')}</div><div class="freeplay-intro">12 张候选，出几张补几张，其他牌留在手边。每关 7 次换牌，用有限的机会凑齐你的构筑。</div><p class="scope-note">${E.BASE_PATTERNS[mode].length} 项基础番型 · 肉鸽计分 · 奇物解锁扩展</p>${button('start','开始新的旅程 <span>→</span>','primary wide')}${resumable?button('continue',`继续上次 · ${E.MODES[game.mode].short} · 第 ${game.round+1} 关`,'secondary wide'):''}<div class="save-note"><span class="live-dot"></span> 进度自动保存在当前浏览器</div>${legacy?'<p class="legacy-note">旧版进度已保留。V4 使用保留候选的新抽牌规则，请另开旅程。</p>':''}</section></main><footer class="home-footer"><span>以牌为径，以奇物为伴。</span><span>单人构筑 · 无需注册</span></footer>`;}
function relicCard(id,act='',extra=''){const r=E.relic(id);return `<article class="relic-card ${r.kind==='秘卷'?'rare':''}"><div class="relic-card-top"><span class="tag">${r.kind}</span>${emblem(id,true)}</div><div class="relic-card-copy"><h3>${r.name}</h3><p>${r.desc}</p></div>${act?button(act,extra||'收入囊中 →','secondary wide',`data-id="${id}"`):''}</article>`;}
function runPath(){return `<nav class="run-path" aria-label="关卡进度">${E.ROUND_NAMES.map((n,i)=>`<div class="path-node ${i===game.round?'current':''} ${i<game.round?'done':''}"><span>${i<game.round?'✓':i===2||i===5?'◆':String(i+1).padStart(2,'0')}</span><small>${n}</small></div>`).join('')}</nav>`;}
function stats(){const target=E.target(game),pct=Math.max(0,Math.min(100,game.totalScore/target*100));return `<aside class="score-column"><section class="score-card"><div class="eyebrow">旅程累计 <span class="tag">${E.MODES[game.mode].short}</span></div><div class="score-number">${fmt(game.totalScore)}</div><div class="target-line">本关门槛 <strong>${fmt(target)}</strong><span>${Math.floor(pct)}%</span></div><div class="progress-track"><i style="width:${pct}%"></i></div><p>${game.totalScore>=target?'累计已达标，仍需完成本关结算':'距门槛还差 '+fmt(target-game.totalScore)+' 分'}</p><p class="carry-note">入关 ${fmt(game.roundStartScore)} · 过程 ${signed(game.processScore)}</p></section><div class="resources">${[['↻','换牌机会',game.swaps],['墨','改牌墨点',game.ink],['◉','铜钱',game.coins],['▤','剩余牌山',game.deck.length]].map(([icon,name,n])=>`<div><span class="resource-icon">${icon}</span><span>${name}</span><strong>${n}</strong></div>`).join('')}</div><div class="round-note"><span>${[2,5].includes(game.round)?'山境试炼':'此间提示'}</span><p>${game.round===2?'风过空谷：初始换牌减少 2 次。':game.round===5?'绝顶寒风：和牌得分 ×0.8。':'分数跨关累计。出单张不消耗额外次数，独行印可带来过程分。'}</p></div>${button('retire','结束本次挑战','text-btn retire')}</aside>`;}
function warning(info){return `<div class="shape-warning ${info.risk==='needs_repair'||info.complete&&!info.legal?'critical':'safe'}" role="status"><b>${info.complete?(info.legal?'牌形成立':'尚未和牌'):info.risk==='needs_repair'?'需要调整牌形':'成型进度'}</b><span>${esc(info.reason)}</span>${info.risk==='needs_repair'?`<small>${info.complete?'可以使用改牌奇物或替换成型牌，再尝试结算。':'仍可继续出牌；改牌奇物或替换成型牌可能带来转机。'}</small>`:''}</div>`;}
function board(){const lock=locked(),info=E.inspect(game);return `<section class="table-area"><div class="table-title"><span>成型区 <small>${E.structuralCount(game)} / 14 位置${game.kongs.length?' · '+game.formed.length+' 张实体牌':''}</small></span>${button('log','计分记录 ↗','text-btn')}</div>${warning(info)}<div class="formed-rack">${game.formed.filter(t=>!lock.has(t.id)).sort((a,b)=>a.face-b.face||Number(a.wild)-Number(b.wild)||a.id.localeCompare(b.id)).map(t=>tile(t,{size:'small',zone:'formed',selected:formedSelected.includes(t.id)})).join('')||(game.kongs.length?'':'<div class="formation-empty"><span>叠 雀</span><p>从备选区出牌，逐步组成这一手。</p></div>')}</div>${game.kongs.length?`<div class="kong-row">${[...game.kongs].sort((a,b)=>a.face-b.face||a.id.localeCompare(b.id)).map(k=>`<div class="kong-group">${k.tileIds.map(id=>tile(game.formed.find(t=>t.id===id),{size:'small',locked:true})).join('')}<small>已声明杠 · 3 位置</small></div>`).join('')}</div>`:''}<div class="hand-toolbar"><span class="muted">${formedSelected.length?'已选 '+formedSelected.length+' 张成型牌':'成型牌可选中，与备选牌等量替换'}</span>${button('replace','替换成型牌 · 1 次','secondary',formedSelected.length>0&&formedSelected.length<=5&&formedSelected.length===selected.length&&game.swaps>0?'':'disabled')}</div></section>`;}
function hand(){const info=E.inspect(game,selected),canCommit=selected.length&&!formedSelected.length&&info.valid;return `<section class="hand-section"><div class="hand-toolbar"><div><strong>候选牌 · ${game.hand.length} 张</strong><span>已选 ${selected.length} 张 · 已摸 ${136-game.deck.length}/136</span></div>${button('clear','取消选择','text-btn',chosen().length?'':'disabled')}</div><p class="batch-note">最多 ${E.DRAW_BATCH_SIZE} 张 · 出几张补几张，其余保留${game.deck.length?" · 换牌每次最多 5 张":" · 牌山已空，不再补牌"}</p><div class="tile-rack">${game.hand.map(t=>tile(t,{zone:'hand',selected:selected.includes(t.id)})).join('')}</div>${selected.length&&!formedSelected.length?`<div class="selection-warning ${info.risk==='needs_repair'?'critical':''}">出牌后：${esc(info.reason)}</div>`:''}<div class="hand-help">${chosen().length?chosen().map(id=>E.tileName([...game.hand,...game.formed].find(t=>t.id===id))).join(' · '):'点击任意张牌。单张、多张均可进入成型区；相同四张可直接声明杠。'}</div><div class="free-actions">${button('transform','✎ 改牌','secondary',chosen().length===1?'':'disabled')}${button('exchange','↻ 换备选牌','secondary',selected.length>0&&selected.length<=5&&!formedSelected.length&&game.swaps>0&&game.deck.length>=selected.length?'':'disabled')}${button('kong','声明杠','secondary',chosen().length===4?'':'disabled')}${button('commit',selected.length?'放入 '+selected.length+' · 补 '+Math.min(selected.length,game.deck.length)+' →':'出选中牌 →','primary',canCommit?'':'disabled')}</div></section>`;}
function buildHintRow(row,fresh=false){
 const labels={active:'已触发',progress:'积累中',support:'辅助',inactive:'未触发'},detail=row.state==='active'?row.detail.replace('已计入当前最佳解释。',''):row.detail;
 return `<article class="build-hint ${row.state==='active'?'is-active':''} ${fresh?'synergy-new':''}" data-build-relic="${esc(row.id)}"><button class="build-hint-title" data-act="relic" data-id="${esc(row.id)}">${emblem(row.id)}<span><b>${esc(row.name)}</b><small>${labels[row.state]||'构筑'}</small></span><strong>${esc(row.effect)}</strong></button>${row.state!=='active'?`<p class="build-progress">${esc(row.progress)}</p>`:''}${detail?`<p class="build-detail">${esc(detail)}</p>`:''}</article>`;
}
function buildPanel(hints){
 const priority=['wheel','mountain','jiang','echo','pair','kong_cauldron'];
 const rows=[...hints.rows].sort((a,b)=>{const rank=x=>x.state==='active'?-20:x.state==='support'?30:priority.includes(x.id)?priority.indexOf(x.id):15;return rank(a)-rank(b);});
 const shown=buildExpanded?rows:rows.slice(0,4),fresh=new Set(hints.justActive||[]);
 const heading=hints.legal?'本手联动已核算':hints.legal===false?'先修复牌形，再触发联动':hints.complete?'等待结算验证':'让奇物一起成势';
 return `<section class="build-panel" aria-label="构筑联动"><div class="build-heading"><span class="section-kicker">构筑联动</span><span class="build-count">${hints.legal?hints.activeIds.length+' 件已触发':'按成型区统计'}</span></div><h3>${heading}</h3><p class="build-caption">${hints.legal?'依据本手最高分解释，收益已计入终局试算。':hints.legal===false?'当前无法和牌，终局计分奇物暂不生效。':hints.complete?'结算预览暂不可用，尚未确认联动。':'目标进度不保证后续摸到所需牌；和牌后统一计分。'}</p><div class="build-hints">${shown.map(row=>buildHintRow(row,fresh.has(row.id))).join('')||'<p class="build-empty">收集奇物，选择这一局想做的组合。</p>'}</div>${rows.length>4?button('build-details',buildExpanded?'收起更多奇物 ↑':'查看其余 '+(rows.length-4)+' 件奇物 ↓','text-btn build-more'):''}</section>`;
}

function previewPanel(p,hints){return `<aside class="preview-column"><section class="preview-card"><div class="eyebrow">终局试算 <span class="preview-dot"></span></div><div class="preview-number">${p.valid?signed(p.delta):'—'}</div>${p.valid&&p.legal?`<div class="formula"><span><strong>${fmt(p.base)}</strong>底分</span><b>×</b><span><strong>${fmt(p.mult)}</strong>倍率</span></div>`:''}<div class="score-detail">${p.valid?`${p.legal?`<span class="finish-tag">${shapeName(p.decomposition.shape)} · ${p.fans} ${E.MODES[game.mode].unit}</span>${p.patterns.map(x=>`<div><span>${x.name}</span><b>+${x.fan}${E.MODES[game.mode].unit}</b></div>`).join('')}${p.gains.map(x=>`<div class="${x.kind==='unlock'?'unlock-line':''}"><span>${x.name}</span><b>${x.kind==='base'?'+'+fmt(x.value)+'底分':x.kind==='addMult'?'+'+fmt(x.value)+'倍率':'×'+fmt(x.value)}</b></div>`).join('')}`:`<p class="critical">当前牌形无法和牌。结算将炸胡，扣除 ${fmt(p.penalty)} 分。</p>`}<div class="cumulative-preview"><span>结算后累计</span><strong>${fmt(p.cumulativeAfter)}</strong><small>${p.passed?'达到门槛，可以过关':'未达 '+fmt(p.target)+'，本次旅程将结束'}</small></div>`:`<p>${esc(p.reason)}。可以自由补牌，也可以选中成型牌替换或改牌。</p>`}</div>${button('settle',p.valid&&!p.legal?'炸胡结算 →':'和牌并结算 →',`primary wide ${p.valid&&!p.legal?'danger-btn':''}`,p.valid?'':'disabled')}<small class="keyboard-hint">每关一次终局结算 · 预览不会消耗资源</small></section></aside>`;}
function relicDock(hints){const active=new Set(hints?.activeIds||[]),fresh=new Set(hints?.justActive||[]);return `<section class="relic-dock"><div class="dock-title"><div class="section-kicker">随行奇物 <span>${game.relics.length} 件${active.size?' · 本手触发 '+active.size+' 件':''}</span></div><span>点击查看效果</span></div><div class="relic-list">${game.relics.map(id=>`<button data-act="relic" data-id="${id}" class="relic-chip ${E.relic(id).kind==='秘卷'?'rare':''} ${active.has(id)?'synergy-active':''} ${fresh.has(id)?'synergy-new':''}">${emblem(id)}<span>${E.relic(id).name}<small>${active.has(id)?'本手已触发':E.relic(id).kind}</small></span></button>`).join('')}</div></section>`;}
function play(){
 const preview=E.currentSettlementPreview(game),hints=buildHints(game,preview),key=game.roundId;
 hints.justActive=key===lastBuildKey?hints.activeIds.filter(id=>!lastActiveIds.has(id)):[];
 lastBuildKey=key;lastActiveIds=new Set(hints.activeIds);
 return `<main class="game-shell">${runPath()}<div class="game-heading"><div><span class="section-kicker">第 ${String(game.round+1).padStart(2,'0')} 关 / 六重山境</span><h1>${E.ROUND_NAMES[game.round]}</h1></div><span class="tag">自由成牌 · 自动择优计分</span></div><div class="play-layout">${stats()}<div class="center-column">${board()}${hand()}${buildPanel(hints)}</div>${previewPanel(preview,hints)}</div>${relicDock(hints)}</main>`;
}
function finalSummary(){const p=game.last;return p?`<div class="final-summary settlement-summary"><div><span>${p.legal?'和牌得分':'炸胡扣分'}</span><strong>${signed(p.delta)}</strong></div><p>${p.legal?p.patterns.map(x=>x.name+' '+x.fan+E.MODES[game.mode].unit).join(' · ')||'基础和牌':'本手未和牌，不获得和牌奖励。'}</p><div><span>累计 ${fmt(p.cumulativeBefore)} → ${fmt(p.cumulativeAfter)}</span><b>${p.passed?'累计达标 · 过关':'累计未达标 · 止步'}</b></div><p>本关门槛 ${fmt(p.target)} · 过程分已计入累计，不重复加分</p></div>`:'';}
function selectionScene(starter=false){return `<main class="choice-scene"><div class="scene-heading"><div class="eyebrow">${starter?'旅程开始 · '+E.MODES[game.mode].name:'第 '+(game.round+1)+' 关已通过'}</div><h1>${starter?'选一件奇物，与你同行。':'山中有奇遇。'}</h1><p>${starter?'稳稳落牌，独自成势，或用一笔改变点数。':'免费选择一件奇物，再去山间小铺整备。'}</p></div>${starter?'':finalSummary()}<div class="choice-grid">${game.offers.map(id=>relicCard(id,starter?'starter':'reward')).join('')}</div><p class="choice-note">奇物效果在持有期间生效，改牌能力也需要对应奇物。</p></main>`;}
function shop(){return `<main class="shop-scene"><div class="scene-heading shop-heading"><div><div class="eyebrow">关间整备 · 山间小铺</div><h1>带上新的可能。</h1><p>累计 ${fmt(game.totalScore)} 分，将带入下一关。</p></div><div class="wallet">◉ <b>${game.coins}</b><small>铜钱</small></div></div><div class="shop-actions"><span>今日奇物 · 已拥有的不会重复出现</span>${button('refresh','刷新货架 · 2 铜钱','secondary',game.coins>=2?'':'disabled')}</div><div class="choice-grid">${game.shop.map(id=>relicCard(id,'buy',`${E.relic(id).price} 铜钱 · 购买`)).join('')||'<p>货架暂空，可以刷新或继续上山。</p>'}</div><section class="shop-owned"><h3>随行奇物 <small>出售返还一半购买价，向下取整</small></h3><div class="owned-row">${game.relics.map(id=>`<div>${emblem(id)}<span>${E.relic(id).name}</span>${button('sell',`售出 +${Math.floor(E.relic(id).price/2)}`,'text-btn',`data-id="${id}"`)}</div>`).join('')}</div></section><div class="shop-next"><div><span class="section-kicker">下一关 · ${E.ROUND_NAMES[game.round+1]}</span><p>累计门槛 ${fmt(E.TARGETS[game.mode][game.round+1])}</p></div>${button('next','继续上山 →','primary')}</div></main>`;}
function ending(){const win=game.phase==='victory';return `<main class="end-scene"><div class="end-seal">${win?'登顶':'再会'}</div><div class="eyebrow">${E.MODES[game.mode].name} · ${win?'六境皆过':'旅程暂歇'}</div><h1>${win?'山高，仍有好牌。':'再叠一手，便是新局。'}</h1><p>${win?'这一程的番型与奇物，组成了你的答案。':`止步于「${E.ROUND_NAMES[game.round]}」，下次奇遇会带来新的方向。`}</p><div class="end-stats"><div><strong>${fmt(game.totalScore)}</strong><span>旅程累计</span></div><div><strong>${fmt(game.bestHand)}</strong><span>最高和牌分</span></div><div><strong>${win?6:game.round} / 6</strong><span>通过关卡</span></div></div>${finalSummary()}${relicDock()}<div class="end-actions">${button('home','重新选择模式','secondary')}${button('restart','同模式再来一局 →','primary')}</div></main>`;}
function settlementScene(){return `<main class="choice-scene"><div class="scene-heading"><div class="eyebrow">第 ${game.round+1} 关 · 结算已保存</div><h1>这一手，落定。</h1><p>重播或刷新不会重复计分。</p></div>${finalSummary()}<div class="end-actions">${button('replay','重播结算','secondary')}${button('settlement-continue','继续 →','primary')}</div></main>`;}
function rules(){const m=screen==='game'&&game?game.mode:mode;return `<div class="rule-intro">单人构筑 · ${E.MODES[m].name}</div><h2>自由落牌，整手成局。</h2><ol class="rule-steps"><li><b>保留候选。</b>136 张牌，起手 12 张候选。出几张补几张，未选牌保留，弃牌不回收。普通手用满 7 次换牌最多看到 61 张（含满 14 后的补牌）；看过的弃牌不能取回。</li><li><b>自由组牌。</b>任意张进入成型区，最终组成四面子一雀头、七对或十三幺；国标还支持组合龙与不靠。系统比较合法解释，自动取奇物联动后的最高分。</li><li><b>调整。</b>一次换 1～5 张备选牌，或等量替换成型牌，都消耗一次换牌。替换后补到 12 张，其他候选保留。入区后不能免费撤回。改牌奇物分别解锁点数、花色、三色万能牌。</li><li><b>声明杠。</b>四张相同有效牌可跨两区声明杠，锁定后占 3 个结构位置，每杠使最终实牌多一张。声明杠只补从候选实际移入的牌数，其他候选保留；纯成型区声明杠不补牌。</li><li><b>结算与闯关。</b>满 14 个结构位置后主动结算，每关一次。和牌分跨关累计，不扣除门槛。炸胡扣本关门槛的 10%（向上取整）；扣后累计仍达标也能过关，否则旅程结束。</li></ol><div class="rule-callout">${m==='mcr'?'国标番型倍率 = 2^(总番 ÷ 8)，每 8 番翻倍。24 番 ×8、48 番 ×64、88 番 ×2,048。':'日麻役种倍率 = 2^(总翻 ÷ 2)，每 2 翻翻倍。4 翻 ×4、8 翻 ×16、13 翻约 ×90.51。'}<br>数牌每张 10、字牌每张 15，完整和牌另加 100 底分。底分奇物先加算，指数倍率后计算倍率奇物和试炼，倍率保留 6 位小数，最终向下取整。过程分独立计入累计。</div><h3>查看完整番型</h3><p>图鉴列出基础支持、奇物扩展以及本作缺少判定条件的项目，并说明覆盖关系。标准大番不需要秘卷解锁。</p>${button('patterns','打开番型图鉴 →','secondary')}<h3>关于风险提醒</h3><p>“需要调整牌形”表示只靠补牌无法成立，仍可继续出牌、改牌或替换。提醒不预测牌山，也不等于绝对无解。最终以改牌、万能牌计算后的牌形为准。</p><h3>规则适配</h3><p>使用肉鸽得分，不使用竞技符数、点棒、国标 8 番起和或日麻起和限制。全程采用门清构筑翻数，但没有自摸、荣和、场风、自风、最终和牌张或暗刻来源，不凭空计算相关役。日麻单役满折算 13 翻，大四喜 26 翻；真实多役满可叠加，并覆盖普通役。国标按番型覆盖关系计分。国标七对允许四同牌拆两对，日麻须七种不同牌。</p><h3>资源与保存</h3><p>每关 7 次换牌、4 点墨。改牌保留实体身份，可产生超过四张相同有效牌；万能牌只替代同点数的万、筒、索，整手使用唯一身份，每关最多一张。第 3 关少 2 次换牌，第 6 关和牌分 ×0.8。V4 新规则与旧存档、旧成绩分开保存。</p>`;}
function dialogContent(){if(dialog==='patterns')return renderPatternGuide({mode:guideMode,filter:guideFilter,query:guideQuery,relics:game?.mode===guideMode?game.relics:[]});if(dialog==='rules')return rules();if(dialog==='log')return `<h2>每次落牌，都有记录。</h2><div class="log-list">${game.log.map(x=>`<div><span>${esc(x.label||x.type||'出牌')}</span><strong>${signed(x.score??x.delta??0)}</strong><p>${esc((x.names||[]).join(' · '))}</p></div>`).join('')||'<p>本关还没有计分记录。</p>'}</div>`;
if(dialog==='transform'){const t=[...game.hand,...game.formed].find(t=>t.id===chosen()[0]),numeric=t&&E.faceValue(t)<27;const enable=(id,cost)=>numeric&&game.relics.includes(id)&&game.ink>=cost?'':'disabled';return `<div class="section-kicker">以墨改牌 · 余 ${game.ink} 点墨</div><h2>把可能，改成机会。</h2><div class="transform-tiles">${tile(t)}</div><p>对应奇物解锁后才能使用。字牌与已声明杠不可改写。</p><h3>升降笔 · 1 墨</h3><div class="transform-actions">${[-1,1].map(n=>button('edit',n===1?'点数 +1':'点数 −1','secondary',`data-edit="rank" data-value="${n}" ${enable('rank_brush',1)}`)).join('')}</div><h3>换色绫 · 1 墨</h3><div class="transform-actions">${['万','筒','索'].map((s,i)=>button('edit','转为'+s,'secondary',`data-edit="suit" data-value="${i}" ${enable('suit_ribbon',1)}`)).join('')}</div><h3>百相玉 · 2 墨</h3><p>保留点数，结算时从三种花色选择唯一身份。每关可生成一张。</p>${button('edit','化为三色万能牌','secondary wide',`data-edit="wild" ${enable('wild_jade',2)}`)}`;}
if(dialog==='risk_commit')return `<h2>这一步，需要后手。</h2><p>出牌后仅靠继续补牌将无法和牌。你仍可用改牌奇物或花换牌次数替换成型牌。</p><p>这不是“绝对无解”的判定，是否继续由你决定。</p><div class="dialog-actions">${button('close','重新选择','secondary')}${button('commit-confirm','仍然出牌','primary')}</div>`;
if(dialog==='risk_settle'){const p=E.currentSettlementPreview(game);return `<h2>${p.legal?'累计尚未达标':'确认炸胡结算？'}</h2><p>${p.legal?'本手可以和牌，但计分后仍未达到本关门槛。':`计算牌形与万能牌后仍无法和牌。本手不获和牌分，将扣除 ${fmt(p.penalty)} 分。`}</p><div class="cumulative-preview"><span>结算后累计</span><strong>${fmt(p.cumulativeAfter)}</strong><small>门槛 ${fmt(p.target)} · ${p.passed?'仍达标，可以过关':'未达标，旅程将结束'}</small></div><p>结算后本关结束，不能再修牌。</p><div class="dialog-actions">${button('close','返回调整','secondary')}${button('settle-confirm','确认结算','primary danger-btn')}</div>`;}
if(dialog==='retire')return `<h2>结束这次旅程？</h2><p>这会放弃当前挑战，保留已有累计分。</p><div class="dialog-actions">${button('close','继续组牌','secondary')}${button('retire-confirm','结束挑战','primary')}</div>`;
if(dialog==='new')return `<h2>开始新的旅程？</h2><p>当前 V4 挑战将被新进度替换。</p><div class="dialog-actions">${button('close','保留进度','secondary')}${button('start-confirm','开始新局','primary')}</div>`;
if(dialog?.relic){const row=game?.phase==='play'?buildHints(game).rows.find(x=>x.id===dialog.relic):null;return relicCard(dialog.relic)+(row?`<div class="relic-build-detail"><h3>本手构筑进度</h3>${buildHintRow(row)}</div>`:'');}return '';}
function render(){document.body.classList.toggle('playing',screen==='game');const f=document.activeElement?.dataset;app.innerHTML=header()+(screen==='home'?home():game.phase==='starter'?selectionScene(true):game.phase==='play'?play():game.phase==='settlement'?settlementScene():game.phase==='reward'?selectionScene():game.phase==='shop'?shop():ending())+(dialog?`<dialog id="modal" class="modal ${dialog==='rules'?'rules-modal':''}"><div class="modal-top">${button('close','×','close-btn','aria-label="关闭弹窗"')}</div>${dialogContent()}</dialog>`:'');app.querySelectorAll('.relic-emblem img').forEach(img=>{img.addEventListener('load',()=>img.previousElementSibling.hidden=true);img.addEventListener('error',()=>img.hidden=true);if(img.complete&&img.naturalWidth)img.previousElementSibling.hidden=true;});if(dialog){const d=document.querySelector('#modal');d.showModal();d.addEventListener('cancel',e=>{e.preventDefault();dialog=null;render();});}else if(f?.act==='tile'){app.querySelector(`[data-act="tile"][data-id="${f.id}"]`)?.focus({preventScroll:true});}}
function start(){const before=capture();game=E.newRun(mode);screen='game';dialog=null;clear();track('start',before,true);persist();render();}
function getPlayer(){return player??=createSettlementPlayer(document.querySelector('#settlement-root'));}
function controls(){wrap.querySelector('[data-act="settlement-mute"]').textContent=sound?'♪ 声音开':'♪ 声音关';wrap.querySelector('[data-act="settlement-speed"]').textContent=speed+'×';wrap.querySelector('[data-act="settlement-motion"]').textContent=reducedMotion?'完整动画':'减弱动画';}
function showSettlement(){wrap.hidden=false;app.inert=true;document.body.classList.add('settlement-open');wrap.querySelector('[data-act="settlement-continue"]').disabled=true;document.querySelector('#settlement-status').textContent='';skipped=false;controls();const before=capture();try{getPlayer().play(buildSettlementSnapshot(game,game.last),{muted:!sound,speed,reducedMotion,onComplete:({status})=>{wrap.querySelector('[data-act="settlement-continue"]').disabled=false;document.querySelector('#settlement-status').textContent=game.last.passed?(game.round===5?'累计达标，继续查看登顶结果。':'累计达标，继续领取奖励。'):'累计未达标，继续查看本次旅程。';track(status==='skipped'?'settlement_skip':'settlement_complete',before,true);}});}catch{document.querySelector('#settlement-root').innerHTML=finalSummary();wrap.querySelector('[data-act="settlement-continue"]').disabled=false;document.querySelector('#settlement-status').textContent='动画暂时不可用，计分结果已保存。';}}
function doSettle(){getPlayer().unlockAudio().catch(()=>{});const before=capture(),result=E.settle(game);track('settle',before,result);if(!result.valid){toast(result.reason);return;}dialog=null;clear();persist();render();showSettlement();}
function continueSettlement(){if(game?.phase!=='settlement')return;const before=capture();E.finishSettlement(game);track('settlement_continue',before,true);persist();wrap.hidden=true;app.inert=false;document.body.classList.remove('settlement-open');player?.dispose();player=null;render();window.scrollTo(0,0);}
function handle(e){const b=e.target.closest('[data-act]');if(!b||b.disabled)return;e.preventDefault();if(e.detail>0)inputMethod='pointer';const a=b.dataset.act;
if(a==='settlement-continue'){continueSettlement();return;}
if(a==='sound'||a==='settlement-mute'){sound=!sound;try{localStorage.setItem(PREF,String(sound));}catch{}player?.setMuted(!sound);if(sound)player?.unlockAudio().catch(()=>{});controls();render();return;}
if(a==='settlement-speed'){speed=speed===1?2:1;player?.setSpeed(speed);controls();return;}
if(a==='settlement-motion'){reducedMotion=!reducedMotion;player?.setReducedMotion(reducedMotion);controls();return;}
if(a==='settlement-skip'){skipped=true;player?.skip();return;}
if(a==='mode'){mode=b.dataset.mode;render();return;}
if(a==='build-details'){buildExpanded=!buildExpanded;render();return;}
if(a==='patterns'){guideMode=screen==='game'&&game?game.mode:mode;guideFilter='all';guideQuery='';dialog='patterns';render();return;}
if(a==='guide-mode'){guideMode=b.dataset.mode;render();return;}
if(a==='guide-filter'){guideFilter=b.dataset.filter;render();return;}
if(a==='rules'){dialog='rules';render();return;}
if(a==='close'){dialog=null;render();return;}
if(a==='home'){screen='home';dialog=null;render();return;}
if(a==='continue'){screen='game';clear();track('resume',capture(),true,{source:'save'});render();return;}
if(a==='start'){if(game&&!['victory','defeat'].includes(game.phase)){dialog='new';render();}else start();return;}
if(a==='start-confirm'){start();return;}
if(a==='restart'){mode=game.mode;start();return;}
if(!game)return;
if(a==='tile'){const before=capture(),id=b.dataset.id,zone=b.dataset.zone;let list=zone==='formed'?formedSelected:selected;list=list.includes(id)?list.filter(x=>x!==id):[...list,id];if(zone==='formed')formedSelected=list;else selected=list;track('select',before,true,{selected_tile_ids:chosen(),source_zone:zone});render();return;}
if(a==='clear'){const before=capture();clear();track('select',before,true,{selected_tile_ids:[]});render();return;}
if(a==='starter'){mutate('starter',()=>E.chooseStarter(game,b.dataset.id),{relic_id:b.dataset.id});return;}
if(a==='commit'){if(E.inspect(game,selected).risk==='needs_repair'){dialog='risk_commit';render();return;}}
if(a==='commit'||a==='commit-confirm'){mutate('commit',()=>E.commit(game,selected),{selected_tile_ids:[...selected],risk_confirmed:a==='commit-confirm'},r=>r.processGain?`已入成型区 · 独行印 +${fmt(r.processGain)} 分`:'已进入成型区，其余候选已保留。');return;}
if(a==='exchange'){mutate('exchange',()=>E.exchange(game,selected),{selected_tile_ids:[...selected]},'备选牌已换新。');return;}
if(a==='replace'){mutate('replace',()=>E.replaceFormed(game,formedSelected,selected),{selected_tile_ids:chosen()},'成型牌已替换，消耗 1 次换牌。');return;}
if(a==='kong'){mutate('kong',()=>E.declareKong(game,chosen()),{selected_tile_ids:chosen()},'杠已声明并锁定，占 3 个结构位置。');return;}
if(a==='transform'){dialog='transform';render();return;}
if(a==='edit'){const kind=b.dataset.edit,value=kind==='wild'?undefined:+b.dataset.value;mutate('transform',()=>E.transform(game,chosen(),kind,value),{selected_tile_ids:chosen(),transform_kind:kind,transform_value:value??null},'牌面已改写。');return;}
if(a==='settle'){const p=E.currentSettlementPreview(game);if(!p.valid){toast(p.reason);return;}if(!p.legal||!p.passed){dialog='risk_settle';render();return;}doSettle();return;}
if(a==='settle-confirm'){doSettle();return;}
if(a==='replay'){getPlayer().unlockAudio().catch(()=>{});showSettlement();return;}
if(a==='reward'){mutate('reward',()=>E.chooseReward(game,b.dataset.id),{relic_id:b.dataset.id});return;}
if(a==='buy'){mutate('buy',()=>E.buy(game,b.dataset.id),{relic_id:b.dataset.id},'奇物已收入囊中。');return;}
if(a==='sell'){mutate('sell',()=>E.sell(game,b.dataset.id),{relic_id:b.dataset.id},'奇物已售出。');return;}
if(a==='refresh'){mutate('refresh_shop',()=>E.refreshShop(game));return;}
if(a==='next'){mutate('next_round',()=>E.nextRound(game));window.scrollTo(0,0);return;}
if(a==='log'){dialog='log';render();return;}
if(a==='relic'){dialog={relic:b.dataset.id};render();return;}
if(a==='retire'){dialog='retire';render();return;}
if(a==='retire-confirm'){mutate('retire',()=>E.retire(game));return;}}
app.addEventListener('input',e=>{if(e.target.id==='pattern-search'){guideQuery=e.target.value;document.querySelector('#pattern-results').innerHTML=renderPatternResults({mode:guideMode,filter:guideFilter,query:guideQuery,relics:game?.mode===guideMode?game.relics:[]});}});
app.addEventListener('click',handle);wrap.addEventListener('click',handle);
document.addEventListener('keydown',e=>{inputMethod='keyboard';if(e.repeat||dialog||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(!wrap.hidden){if(e.key==='Escape'){e.preventDefault();skipped=true;player?.skip();}return;}if(e.key==='Escape'){const before=capture();clear();track('select',before,true,{selected_tile_ids:[]});render();}if(e.key==='Enter'&&screen==='game'&&game?.phase==='play'&&(e.target.tagName!=='BUTTON'||e.target.dataset.act==='tile')&&e.target.tagName!=='A'){const b=app.querySelector(`[data-act="${selected.length?'commit':'settle'}"]`);if(b&&!b.disabled){e.preventDefault();b.click();}}});
render();
